from __future__ import annotations

import re

_ALIGNMENTS = (None, "left", "right", "center")
_DELIMITER_RE = re.compile(r"^:?-+:?$")
_UNESCAPED_PIPE_RE = re.compile(r"(?<!\\)\|")


def _cell_text(value: object) -> str:
    """The table text for a value, escaping pipes."""
    if value is None:
        return ""
    return str(value).replace("|", "\\|")


def _pad(text: str, width: int, alignment: str | None) -> str:
    """Pad ``text`` to ``width`` according to ``alignment``."""
    padding = width - len(text)
    if alignment == "right":
        return " " * padding + text
    if alignment == "center":
        left = padding // 2
        return " " * left + text + " " * (padding - left)
    return text + " " * padding


def _delimiter_cell(width: int, alignment: str | None) -> str:
    """The delimiter cell for a column of ``width``."""
    if alignment == "left":
        return ":" + "-" * (width - 1)
    if alignment == "right":
        return "-" * (width - 1) + ":"
    if alignment == "center":
        return ":" + "-" * (width - 2) + ":"
    return "-" * width


def _split_cells(line: str) -> list[str]:
    """Split one table line into stripped, unescaped cells."""
    line = line.strip()
    if line.startswith("|"):
        line = line[1:]
    if line.endswith("|") and not line.endswith("\\|"):
        line = line[:-1]
    return [
        cell.strip().replace("\\|", "|") for cell in _UNESCAPED_PIPE_RE.split(line)
    ]


def _split_line(line: str) -> list[str]:
    """Split one table line into stripped cells, before unescaping."""
    line = line.strip()
    if line.startswith("|"):
        line = line[1:]
    if line.endswith("|") and not line.endswith("\\|"):
        line = line[:-1]
    return [cell.strip() for cell in _UNESCAPED_PIPE_RE.split(line)]


def format_table(
    header: list, rows: list[list], align: list[str | None] | None = None
) -> str:
    """Write a Markdown table."""
    columns = len(header)
    if align is None:
        alignments: list[str | None] = [None] * columns
    else:
        if not isinstance(align, list):
            raise ValueError("align must be a list with one entry per column")
        if len(align) != columns:
            raise ValueError("align must have one entry per column")
        alignments = list(align)

    for alignment in alignments:
        if alignment not in _ALIGNMENTS:
            raise ValueError(f"invalid alignment: {alignment!r}")

    header_cells = [_cell_text(value) for value in header]
    row_cells: list[list[str]] = []
    for row in rows:
        if len(row) > columns:
            raise ValueError("row has more cells than the header")
        cells = [_cell_text(value) for value in row]
        cells.extend([""] * (columns - len(cells)))
        row_cells.append(cells)

    widths = [max(3, len(cell)) for cell in header_cells]
    for cells in row_cells:
        for index, cell in enumerate(cells):
            widths[index] = max(widths[index], len(cell))

    def render(cells: list[str]) -> str:
        return "| " + " | ".join(
            _pad(cell, width, alignment)
            for cell, width, alignment in zip(cells, widths, alignments)
        ) + " |"

    lines = [render(header_cells)]
    lines.append("| " + " | ".join(
        _delimiter_cell(width, alignment)
        for width, alignment in zip(widths, alignments)
    ) + " |")
    lines.extend(render(cells) for cells in row_cells)
    return "\n".join(lines)


def parse_table(
    text: str,
) -> tuple[list[str], list[list[str]], list[str | None]]:
    """Read a Markdown table into its header, rows, and alignments."""
    lines = text.splitlines()
    if len(lines) < 2:
        raise ValueError("table must have at least two lines")

    header = _split_cells(lines[0])
    delimiter = _split_line(lines[1])
    if len(delimiter) != len(header):
        raise ValueError("delimiter line has a different number of cells than the header")

    alignments: list[str | None] = []
    for cell in delimiter:
        if not _DELIMITER_RE.fullmatch(cell):
            raise ValueError(f"invalid delimiter cell: {cell!r}")
        if cell.startswith(":") and cell.endswith(":"):
            alignments.append("center")
        elif cell.startswith(":"):
            alignments.append("left")
        elif cell.endswith(":"):
            alignments.append("right")
        else:
            alignments.append(None)

    rows: list[list[str]] = []
    for line in lines[2:]:
        row = _split_cells(line)
        if len(row) != len(header):
            raise ValueError("row has a different number of cells than the header")
        rows.append(row)

    return header, rows, alignments

